head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDODS70101";
scwin.pageSize = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_tgtIsuSrtCd", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["repIsuSrtCd"] ?? ""); } },
        { childId: "ipt_tgtIsurCd_2", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["isurCd"] ?? ""); } },
        { childId: "ipt_tgtFssUnqNo_2", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["fssUnqNo"] ?? ""); } },
        { childId: "ipt_tgtIsuSrtCd_2", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["repIsuSrtCd"] ?? ""); } },
        { childId: "ipt_tgtComNm_2", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["comNm"] ?? ""); } },
        { childId: "ipt_disclsTitle", fn: function () { return String((dma_pageContext.get("disclsTitle") ?? "")); } },
        { childId: "__rb0", fn: function () { return "전체 " + String(dma_docPage.get("total")) + "건 [" + String(dma_docPage.get("currentPage")) + "/" + String(dma_docPage.get("endListPage")) + " 페이지]"; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name initPageIndex
 * @description init Page Index 처리
 * @returns {void}
 * @hidden N
 */
scwin.initPageIndex = function () {
    $c.util.getComponent('dma_deleteDoReq').set('pageIndex', "1");
};

// 세션 사용자 결선 (어휘 session_attribute 2건 — gcc $c.session.getUserInfo)

/**
 * @method
 * @name init_sessionFill
 * @description 초기화 — session Fill
 * @returns {void}
 * @hidden N
 */
scwin.init_sessionFill = function () {
    const names = ["corpUsrTpCd","exmptObjDisclsYn"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldods70101' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

// [A] 초기 목록 미해결 — jldods70101: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.pageSize = "" + dma_pageContext.get("pageSize") + "";
        scwin.init_rowCopy();
        scwin.init_sessionFill();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldods70101.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_disclsTitle_onkeyup
 * @description ipt_disclsTitle 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_disclsTitle_onkeyup = async function(e){
    try {
        await scwin.enterSearchForm();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70101.ipt_disclsTitle_onkeyup' }); }
};

/**
 * @method
 * @name input_53_onclick
 * @description 「검색」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.input_53_onclick = async function(e){
    try {
        await scwin.searchList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70101.input_53_onclick' }); }
};

/**
 * @method
 * @name slc_pageSize_onchange
 * @description slc_pageSize 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_pageSize_onchange = async function(e){
    try {
        scwin.initPageIndex(); await scwin.searchList();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70101.slc_pageSize_onchange' }); }
};

/**
 * @method
 * @name grd_docPageList_oncellclick
 * @description grd_docPageList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_docPageList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_docPageList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_docPageList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: fn_goWrite('${doc.applNo}', '${doc.formCd}', '${doc.formVer}', '${doc.currFormVer}', '${doc.currEngFormVer}', '${doc.beforeFormVer}', '${doc.beforeEngFormVer}', '${doc.oldFormVerUseYn}', '${subdoc.docNo}', '${subdoc.formCd}', '${subdoc.formVer}', '${doc.langTpCd}', '${doc.disclsObjCorpIsurCd}', '${doc.disclsObjCorpFssUnqNo}', '${doc.disclsAcptTpCd}', '${subdoc.wrtrptMaindocTpCd}', '${doc.disclsObjCorpIsurNm}', '${doc.subcomDisclsYn }', '${doc.formUpclssCd }', '${fn:replace(doc.comEngAbbrv, '\'', '\\'') }', '${doc.disclsObjRepIsuSrtCd}', '${doc.exmptObjDisclsYn}', '${doc.disclsObjIsuCd}'); (EL 미해석) */
        scwin.delete(r["applNo"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_docPageList.oncellclick' });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_delete_do
 * @description delete do 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_delete_do = async function () {
    const sbmOptions = {
        id: "tx_fn_delete_do",
        method: "post",
        action: "/discls/searchDisclosureDocument.do?method=removeWritingDocument",
        ref: "dma_deleteDoReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_goWrite
 * @description go Write 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goWrite = async function () {
    const sbmOptions = {
        id: "tx_fn_goWrite",
        method: "post",
        action: "/discls/disclosure.do?method=disclosureCreate",
        ref: "dma_goWriteReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_goPrint
 * @description go Print 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goPrint = async function () {
    try { return await $c.data.downFile("/submission/disclosure.do?method=searchDisclosureContentPrint", "", ($c.util.getComponent("dma_goPrintReq") ? $c.util.getComponent("dma_goPrintReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_docPageList_fmt_column3
 * @description grd doc Page List fmt column3 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_docPageList_fmt_column3 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_docPageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "wrtrptMaindocTpCd") ?? '') : '');
        if (v === '1') { return "재작성요청 임시저장"; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_docPageList.column3" }); return String(data ?? ''); }
};

/**
 * @method
 * @name enterSearchForm
 * @description enter Search Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.enterSearchForm = async function () {
    if (event.keyCode === 13) {
        await scwin.searchList();
    }
};

/**
 * @method
 * @name searchList
 * @description search List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchList = async function () {
    if ($c.util.getComponent('ipt_fromDate').getValue()> $c.util.getComponent('ipt_toDate').getValue()) {
        await alertE('시작일자는 종료일자 이전 이어야 합니다.');
        return;
    }
    blockLoading();
    /* 수동 전환 필요: searchForm.submit() — as-is 자기제출(action 없음), 대체 tx 미정 */ await $c.win.alert("이 동작은 아직 전환되지 않았습니다(as-is 폼 «searchForm» 자기제출 — 대체 서버 호출 미정).");
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @param {*} applNo applNo
 * @returns {void}
 * @hidden N
 */
scwin.delete = function (applNo) {
    confirmF("삭제하시겠습니까?", async function() {
            await scwin.deleteDo(applNo);
    });
};

/**
 * @method
 * @name deleteDo
 * @description delete Do 처리
 * @param {*} applNo applNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.deleteDo = async function (applNo) {
    $c.util.getComponent("dma_deleteDoReq").set("applNo", applNo);
    await scwin.tx_fn_delete_do();
};

/**
 * @method
 * @name goWrite
 * @description go Write 처리
 * @param {*} applNo applNo
 * @param {String} disclsMaindocFormCd disclsMaindocFormCd
 * @param {*} disclsMaindocFormVer disclsMaindocFormVer
 * @param {*} currFormVer currFormVer
 * @param {*} currEngFormVer currEngFormVer
 * @param {*} beforeFormVer beforeFormVer
 * @param {*} beforeEngFormVer beforeEngFormVer
 * @param {String} oldFormVerUseYn oldFormVerUseYn
 * @param {*} docNo docNo
 * @param {String} formCd formCd
 * @param {*} formVer formVer
 * @param {String} langTpCd langTpCd
 * @param {String} tgtIsurCd tgtIsurCd
 * @param {*} tgtFssUnqNo tgtFssUnqNo
 * @param {String} disclsAcptTpCd disclsAcptTpCd
 * @param {String} wrtrptMaindocTpCd wrtrptMaindocTpCd
 * @param {String} disclsObjCorpIsurNm disclsObjCorpIsurNm
 * @param {String} subcomDisclsYn subcomDisclsYn
 * @param {String} formUpclssCd formUpclssCd
 * @param {String} tgtComEngNm tgtComEngNm
 * @param {String} disclsObjRepIsuSrtCd disclsObjRepIsuSrtCd
 * @param {String} exmptObjDisclsYn exmptObjDisclsYn
 * @param {String} disclsObjIsuCd disclsObjIsuCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goWrite = async function (applNo, disclsMaindocFormCd, disclsMaindocFormVer, currFormVer, currEngFormVer, beforeFormVer, beforeEngFormVer, oldFormVerUseYn, docNo, formCd, formVer, langTpCd, tgtIsurCd, tgtFssUnqNo, disclsAcptTpCd, wrtrptMaindocTpCd, disclsObjCorpIsurNm, subcomDisclsYn, formUpclssCd, tgtComEngNm, disclsObjRepIsuSrtCd, exmptObjDisclsYn, disclsObjIsuCd) {
    $c.util.getComponent("dma_deleteDoReq").set("applNo", applNo);
    if (docNo !== '00000000000000') {
        $c.util.getComponent('dma_deleteDoReq').set('docNo', docNo);
    }
    $c.util.getComponent("dma_deleteDoReq").set("disclsMaindocFormVer", disclsMaindocFormVer);
    $c.util.getComponent("dma_deleteDoReq").set("formVer", formVer);
    $c.util.getComponent('dma_deleteDoReq').set('disclsMaindocFormCd', disclsMaindocFormCd);
    $c.util.getComponent('dma_deleteDoReq').set('formCd', formCd);
    $c.util.getComponent("dma_deleteDoReq").set("langTpCd", langTpCd);
    $c.util.getComponent("dma_deleteDoReq").set("tgtIsurCd", tgtIsurCd);
    $c.util.getComponent("dma_deleteDoReq").set("tgtIsuCd", disclsObjIsuCd);
    $c.util.getComponent("dma_deleteDoReq").set("tgtFssUnqNo", tgtFssUnqNo);
    $c.util.getComponent("dma_deleteDoReq").set("tgtComNm", disclsObjCorpIsurNm);
    $c.util.getComponent("dma_deleteDoReq").set("tgtIsuSrtCd", disclsObjRepIsuSrtCd);
    $c.util.getComponent('dma_deleteDoReq').set('tgtComEngNm', tgtComEngNm);
    $c.util.getComponent('dma_deleteDoReq').set('disclsAcptTpCd', disclsAcptTpCd);
    $c.util.getComponent('dma_deleteDoReq').set('wrtrptMaindocTpCd', wrtrptMaindocTpCd);
    $c.util.getComponent('dma_deleteDoReq').set('subcomDisclsYn', subcomDisclsYn);
    $c.util.getComponent('dma_deleteDoReq').set('formUpclssCd', formUpclssCd);
    $c.util.getComponent('dma_deleteDoReq').set('exmptObjDisclsYn', exmptObjDisclsYn);
    await scwin.tx_fn_goWrite();
};

/**
 * @method
 * @name goPrint
 * @description go Print 처리
 * @returns {void}
 * @hidden N
 */
scwin.goPrint = function () {

    // TODO : 확인 후 작업 필요....
    //        printWin = window.open("", "printWin", "scrollbars=yes,resizable=yes,status=yes,toolbar=no,menubar=yes,width=700,height=550");

    //        (document.printFrm || { elements: [] }).target = 'printWin';
    //        (document.printFrm || { elements: [] }).action = '/submission/disclosure.do?method=searchDisclosureContentPrint';
    //        await scwin.tx_fn_goPrint();

};

/**
 * @method
 * @name alertE
 * @description alert E 처리
 * @param {String} msg 항목명
 * @param {*} callback callback
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.alertE = async function (msg, callback) {
    // as-is 는 화면 안 #pAlertText/#divAlertMsg 를 만졌다 — 엔진 프레임 접두 때문에
    // 그 선택자는 어디서도 못 찾는다. 표준 알림으로 낸다(메시지가 사라지지 않게).
    await $c.win.alert(msg);
    if (typeof callback === 'function') { await callback(); }
};

async function alertE(msg, callback) { return await scwin.alertE(msg, callback); }

/**
 * @method
 * @name krxpage_pagenavigator_116_onclick
 * @description krxpage_pagenavigator_116 클릭 이벤트
 * @param {Number} index index
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.krxpage_pagenavigator_116_onclick = async function (index) {
    try {
        const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index;
        $c.util.getComponent('dma_deleteDoReq').set('pageIndex', pi);
        await scwin.searchList();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldods70101.krxpage_pagenavigator_116_onclick" });
    }
};
